/* ── load-time invariants: the bank refuses to load rather than serve a broken item ─────────── */
const seen = new Set();
for (const [topic, items] of Object.entries(TOPIC_QUIZZES)) {
  if (!/^T0[1-9]$/.test(topic)) throw new Error(`question bank: ${topic} is not a PRINS2-1 topic code`);
  if (items.length < 3) throw new Error(`question bank: ${topic} has ${items.length} primary questions; 22 TAC 535.62(b)(7) requires at least three`);
  for (const item of items) {
    if (seen.has(item.id)) throw new Error(`question bank: duplicate item id ${item.id}`);
    seen.add(item.id);
    if (!item.tests.startsWith(topic)) throw new Error(`question bank: ${item.id} tests ${item.tests}, which is not a unit of ${topic}`);
    if (item.choices.length !== 4) throw new Error(`question bank: ${item.id} must offer four choices`);
    if (item.correctChoice !== 0) throw new Error(`question bank: ${item.id} must author the correct answer first`);
    if (!item.rationale || item.rationale.length < 80) throw new Error(`question bank: ${item.id} needs a teaching rationale`);
    if (!/^module-\d+\.md#unit-/.test(item.remediation)) throw new Error(`question bank: ${item.id} remediation anchor is malformed`);
    const r = item.replacement;
    if (!r || r.id !== `${item.id}R`) throw new Error(`question bank: ${item.id} needs a replacement with id ${item.id}R`);
    if (seen.has(r.id)) throw new Error(`question bank: duplicate replacement id ${r.id}`);
    seen.add(r.id);
    if (r.choices.length !== 4) throw new Error(`question bank: ${r.id} must offer four choices`);
    if (r.correctChoice !== 0) throw new Error(`question bank: ${r.id} must author the correct answer first`);
    if (!r.rationale || r.rationale.length < 80) throw new Error(`question bank: ${r.id} needs a teaching rationale`);
    /* The rule requires a SUBSEQUENT RELATED question, not the same one again. */
    if (r.prompt === item.prompt) throw new Error(`question bank: ${r.id} repeats its primary's prompt`);
  }
}

export const PRIMARY_COUNT = Object.values(TOPIC_QUIZZES).reduce((n, items) => n + items.length, 0);
export const REPLACEMENT_COUNT = PRIMARY_COUNT;
export const ALL_ITEMS = Object.freeze(Object.entries(TOPIC_QUIZZES).flatMap(([topic, items]) => items.map((i) => Object.freeze({ ...i, topic }))));

export default Object.freeze({ TOPIC_QUIZZES, ALL_ITEMS, PRIMARY_COUNT, REPLACEMENT_COUNT });
